function setup(){show(`<span class="eyebrow">THE DEAL IS SIMPLE</span><h2>Stay off this device.</h2><p>He works. You work elsewhere. Keep coming back to the screen, and he’ll make it your problem.</p><label for="task">What are you getting done?</label><input id="task" maxlength="100" placeholder="That problem sheet. Finally."><div class="form-row"><div><label for="minutes">Focus minutes</label><input id="minutes" type="number" min="1" max="180" step="1" value="${duration}"></div><div><label for="break">Break afterwards</label><select id="break"><option value="5">5 minutes</option><option value="10" selected>10 minutes</option><option value="15">15 minutes</option></select></div></div><label>How does he catch you?</label><label class="choice"><input type="radio" name="mode" value="camera" checked><span><b>Webcam · notice my gaze</b><small>Calibrate first. Your face stays on this device. Works best with your work beside or below the screen.</small></span></label><label class="choice"><input type="radio" name="mode" value="pointer"><span><b>Mouse / touch · notice me interacting</b><small>Move your mouse or touch this page and suspicion grows. Stop interacting and it drops. No camera.</small></span></label><p class="note">Leaving this tab pauses class and loses the perfect bonus. This website cannot block other apps or detect mouse movement outside this page.</p><button class="primary" id="setup-next">Let’s do this</button>`);$('#setup-next').onclick=()=>{const n=Number($('#minutes').value);if(!Number.isInteger(n)||n<1||n>180){toast('Choose 1–180 whole minutes.');return;}duration=n;const options={total:n*60,task:$('#task').value.trim()||'Head down. Work done.',mode:$('input[name="mode"]:checked').value,breakMinutes:Number($('#break').value),demo:false};close();options.mode==='camera'?cameraSetup(()=>begin(options)):begin(options);};}
