if(document.modelContext?.registerTool){const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'get_focus_status',description:'Read the current focus session and local class progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object.');return{session:session?{mode:session.mode,paused:session.paused,remaining:Math.ceil(remaining())}:null,rank:rankFor(profile.rp).label,credits:profile.credits};}},{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
